1	// 首页“创建公开房间”在创建请求连接失败时的界面回归测试。
2	//
3	// 与其他浏览器回归文件的分工：
4	//   - ui.test.mjs：创建成功/被拒（服务返回业务原因）、成功后列表竞态刷新、
5	//     名称整理与长度边界；
6	//   - ui-capacity-linkage.test.mjs / ui-turn-seconds.test.mjs / ui-mixed-records.test.mjs：
7	//     人数联动、时间限制与混合记录展示；
8	//   - 本文件只盯住“创建请求尚未送达服务就连接失败”这一条路径：此时没有服务端
9	//     返回的业务拒绝原因，也没有已确认的新房间编号，页面必须沿用现有的连接失败
10	//     反馈（“无法连接服务，请确认服务仍在运行后重试。”），不能显示成输入错误
11	//     或房间列表读取失败。
12	//
13	// 覆盖的产品行为：
14	//   1. 用户先看到正常加载的已有房间，再填写一份合法的飞行棋配置（4 人、60 秒、
15	//      名称含首尾空格、内部空格与表情）；
16	//   2. 提交进入等待时创建按钮暂时不可用；连接失败后表单区域显示连接失败提示，
17	//      按钮恢复可用；名称保持输入时的原貌，规则、人数、时间全部保留，人数选择
18	//      仍然可用，不退回“未选择规则”的初始状态；
19	//   3. 房间列表保留提交前的内容与排列次序，不出现新房间、成功提示或虚假编号；
20	//      服务端查询到的房间记录没有增加，已有记录及其附带字段保持原值；
21	//   4. 连接恢复后用户不刷新页面、不重新填写，直接再次提交即可正常创建：新房间
22	//      使用保留的飞行棋/4 人/60 秒配置，名称仅去掉首尾空白（内部空格与表情保留），
23	//      成功提示中的非空编号与服务端返回一致，列表在已有记录之后展示新房间且原有
24	//      记录内容与次序不变；连接失败提示被成功结果替换，表单恢复初始填写状态
25	//      （名称/时间为空、规则未选择、人数不可填写），创建按钮仍可使用。
26	//
27	// 失败条件限定为“请求未送达服务”（用请求拦截在请求发出前中止来模拟，并以
28	// 服务端记录数不变佐证请求确实没有到达）；响应途中断开时房间是否已保存不在
29	// 本文件的判断范围内。既有区分继续保留：服务已确认创建成功、仅后续列表刷新
30	// 连接失败时，仍保留成功提示及编号，不按创建连接失败处理（本文件第二个用例
31	// 在连接层面覆盖这一区分，HTTP 层由 ui.test.mjs 覆盖）。
32	//
33	// 运行：npm test（需要系统 Chrome，可用 CHROME_PATH 指定路径）。
34	
35	import { test, before, after } from 'node:test';
36	import assert from 'node:assert/strict';
37	import { execFile, spawn } from 'node:child_process';
38	import { mkdtemp, writeFile, rm } from 'node:fs/promises';
39	import { tmpdir } from 'node:os';
40	import path from 'node:path';
41	import { promisify } from 'node:util';
42	import puppeteer from 'puppeteer-core';
43	
44	const repoRoot = import.meta.dirname;
45	const chromePath = process.env.CHROME_PATH || '/usr/bin/google-chrome';
46	
47	const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
48	
49	let serverBin;
50	let browser;
51	
