1	// 首页“创建公开房间”在“服务已返回 201 成功状态，但创建结果未能确认”时的
2	// 界面回归测试。
3	//
4	// 与其他浏览器回归文件的分工：
5	//   - ui.test.mjs：创建成功/被拒（服务返回业务原因）、成功后列表竞态刷新；
6	//   - ui-create-connection-failure.test.mjs：创建请求“尚未送达服务”就连接失败；
7	//   - ui-pending-edit.test.mjs：等待期间继续编辑时的提交快照与表单保留；
8	//   - 本文件只盯住“201 已到达、但房间编号没有可靠拿到”这一条容易误导用户
9	//     重复创建的路径：正文没能完整读出（连接在正文传完前断开）、正文不是
10	//     合法 JSON，或正文可解析但没有非空字符串编号（缺失、空字符串、数字、
11	//     null、数组等类型不符）。这几种情形必须同一种处理：
12	//     表单区域继续显示“创建结果未能确认”的提醒，说明服务已返回成功状态、
13	//     房间可能已经保存，请先刷新页面查看房间列表再决定是否重新提交；
14	//     不能显示“房间已创建”及编号，不能换成输入错误或“无法连接服务”。
15	//
16	// 关键在于“不确定”而非“失败”：201 意味着服务端处理可能已经落盘，页面没有
17	// 有效编号时只能表达不确定，不能因没有成功提示就断定服务端没有新增记录。
18	// 因此本文件不用纯浏览器拦截凭空构造响应（那样请求根本没到服务端），而是在
19	// 真实服务前放一个仅用于测试的转发代理：创建请求照常转发、服务端真实保存，
20	// 代理读到完整的 201 响应后，再按用例把发给浏览器的正文替换成截断/非法/缺
21	// 编号的内容。这样可以同时验证两端：
22	//   - 页面侧：没有编号就只显示不确定提醒、保留四项当前填写、不拼新行、
23	//     不自动刷新列表、不自动再次发送创建请求、按钮恢复可用且仍可编辑；
24	//   - 服务端侧：房间确实已经保存（真实编号、提交时配置），用户按提醒刷新
25	//     页面后能看到这次房间，等待期间的编辑没有自动生成另一间房。
26	//
27	// 既有区分继续保留：完整的创建结果仍按正常成功处理（显示返回编号、复位表单
28	// 并刷新列表，本文件末尾用例在代理透传下锁定）；已确认成功但列表刷新失败
29	// 仍保留成功提示与编号（本文件末尾用例锁定 HTTP 层区分，连接层区分见
30	// ui-create-connection-failure.test.mjs）；请求未送达的连接失败文案与行为
31	// 由 ui-create-connection-failure.test.mjs 专门保障。
32	//
33	// 运行：npm test（需要系统 Chrome，可用 CHROME_PATH 指定路径）。
34	
35	import { test, before, after } from 'node:test';
36	import assert from 'node:assert/strict';
37	import http from 'node:http';
38	import { execFile, spawn } from 'node:child_process';
39	import { mkdtemp, writeFile, rm } from 'node:fs/promises';
40	import { tmpdir } from 'node:os';
41	import path from 'node:path';
42	import { promisify } from 'node:util';
43	import puppeteer from 'puppeteer-core';
44	
45	const repoRoot = import.meta.dirname;
46	const chromePath = process.env.CHROME_PATH || '/usr/bin/google-chrome';
47	
48	const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
49	
50	let serverBin;
51	let browser;
52	
53	// 与其他界面回归文件相同的种子记录：验证不确定结果前后列表内容与次序不变，
54	// 以及刷新后新房间只追加在种子记录之后。
55	const SEED_ALPHA =
56	  '{"id":"seed-alpha","name":"晨间飞行棋","game":"ludo","capacity":4,"turnSeconds":30,' +
57	  '"status":"playing","visibility":"public","createdAt":"2026-01-01T08:00:00Z","note":"保留我","tags":["老友","周赛"]}';
58	const SEED_BETA =
59	  '{"id":"seed-beta","name":"午夜五子棋","game":"gomoku","capacity":2,"turnSeconds":0,' +
60	  '"status":"waiting","visibility":"public","createdAt":"2026-01-02T23:00:00Z","extra":{"rank":3}}';
61	
62	const SUCCESS_PREFIX = '房间已创建，编号：';
63	const CONN_FAILURE_TEXT = '无法连接服务，请确认服务仍在运行后重试。';
64	const LIST_ERROR_TEXT = '房间列表加载失败，请稍后刷新重试。已有数据不会因此丢失。';
65	// 不确定提醒须与 index.html 完全一致（含全角冒号、逗号与句号）。
66	const UNCONFIRMED_TEXT =
67	  '创建结果未能确认：服务已返回成功状态，但回应内容未能完整读取，' +
68	  '房间可能已经保存。请先刷新页面查看房间列表，确认是否已创建后，再决定是否重新提交。';
69	
70	// 正常成功后表单复位状态：名称/时间为空、规则未选、人数不可填。
71	const RESET_FORM = {
72	  name: '',
73	  game: '',
74	  capacity: '',
75	  capacityDisabled: true,
76	  turnSeconds: '',
77	  submitDisabled: false,
78	};
79	
80	before(async () => {
81	  const dir = await mkdtemp(path.join(tmpdir(), 'score-arena-uibin-'));
82	  serverBin = path.join(dir, 'score-arena');
83	  await promisify(execFile)('go', ['build', '-o', serverBin, '.'], { cwd: repoRoot });
84	  browser = await puppeteer.launch({
85	    executablePath: chromePath,
86	    headless: true,
87	    args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'],
88	  });
89	});
90	
91	after(async () => {
92	  if (browser) await browser.close();
93	  if (serverBin) await rm(path.dirname(serverBin), { recursive: true, force: true });
94	});
95	
96	// startServer 在 dataDir 上启动真实服务子进程（--port 0 自动选端口），返回基地址。
97	function startServer(t, dataDir) {
98	  const proc = spawn(
99	    serverBin,
100	    ['serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dataDir],
101	    { stdio: ['ignore', 'pipe', 'inherit'] },
102	  );
103	  t.after(() => { proc.kill('SIGKILL'); });
104	  return new Promise((resolve, reject) => {
105	    let buf = '';
106	    const timer = setTimeout(() => reject(new Error('等待服务监听地址超时')), 15000);
107	    proc.stdout.on('data', (chunk) => {
108	      buf += chunk.toString();
109	      const m = buf.match(/listening on (http:\/\/\S+)/);
110	      if (m) {
111	        clearTimeout(timer);
112	        resolve(m[1]);
113	      }
114	    });
115	    proc.on('exit', (code) => {
116	      clearTimeout(timer);
117	      reject(new Error(`服务在输出监听地址前退出，退出码 ${code}`));
118	    });
119	  });
120	}
121	
122	async function seedRooms(dataDir, ...records) {
123	  await writeFile(path.join(dataDir, 'rooms.json'), '[\n' + records.join(',\n') + '\n]\n');
124	}
125	
126	// startProxy 在真实服务前启动一个只用于测试的转发代理，页面通过代理地址访问。
127	// 默认透传所有请求/响应；选项：
128	//   - corruptPost(info)：每次 POST /api/rooms 在“真实服务的完整响应已经到达
129	//     代理”之后被调用，info 含真实 status、解析出的 room（真实保存结果）与
130	//     请求体原文。返回（可 await）：
131	//       null/undefined        → 原样透传真实响应；
132	//       { truncate: true, body }
133	//                             → 回 201 但声明的 Content-Length 大于实际正文，
134	//                               写出 body 后断开连接，模拟正文未能完整读出；
135	//       { body }              → 回 201 与指定完整正文（可为非法 JSON 或缺
136	//                               编号的 JSON）。
137	//   - corruptGet(info)：对 GET /api/rooms 同样在真实响应到达后调用，返回
138	//     { status, body } 替换响应或 null 透传（用于列表刷新失败区分用例）。
139	// 代理把服务端处理与浏览器收到的内容分开：即使浏览器拿到的是残缺正文，真实
140	// 服务上的创建也已经落盘，info.room 里是服务端生成的真实编号。
141	function startProxy(t, realPort, options = {}) {
142	  const counts = { getRooms: 0, postRooms: 0 };
143	  const posts = [];
144	  // 记录所有代理监听上的连接，关闭时主动销毁：浏览器对代理保持 keep-alive，
145	  // 否则 server.close() 会一直等待空闲连接，拖慢甚至挂住用例清理。
146	  const sockets = new Set();
147	  const server = http.createServer((req, clientRes) => {
148	    const isRoomsApi = req.url.endsWith('/api/rooms');
149	    if (isRoomsApi && req.method === 'GET') counts.getRooms++;
150	    if (isRoomsApi && req.method === 'POST') counts.postRooms++;
151	
152	    const reqChunks = [];
153	    req.on('data', (c) => reqChunks.push(c));
154	    req.on('error', () => clientRes.destroy());
155	
156	    const forward = () => {
157	      const proxyReq = http.request({
158	        hostname: '127.0.0.1',
159	        port: realPort,
160	        path: req.url,
161	        method: req.method,
162	        headers: { ...req.headers, host: `127.0.0.1:${realPort}` },
163	      }, (proxyRes) => {
164	        const upChunks = [];
165	        proxyRes.on('data', (c) => upChunks.push(c));
166	        proxyRes.on('error', () => { if (!clientRes.writableEnded) clientRes.destroy(); });
167	        proxyRes.on('end', async () => {
168	          const realBody = Buffer.concat(upChunks);
169	
170	          // 每一次 POST 都记录真实响应（含真实保存结果），与是否替换正文无关，
171	          // 这样透传对照用例也能拿到服务端生成的编号。
172	          if (isRoomsApi && req.method === 'POST') {
173	            let room = null;
174	            try { room = JSON.parse(realBody.toString('utf8')); } catch { room = null; }
175	            const info = {
176	              index: posts.length,
177	              status: proxyRes.statusCode,
178	              room,
179	              reqBody: Buffer.concat(reqChunks).toString('utf8'),
180	            };
181	            posts.push(info);
182	            const spec = options.corruptPost ? await options.corruptPost(info) : null;
183	            if (spec) {
184	              if (spec.truncate) {
185	                // 声明一个比实际正文更长的 Content-Length，写出部分正文后断开：
186	                // 浏览器能收到 201 状态行，但正文读取失败（resp.json() 拒绝）。
187	                clientRes.writeHead(spec.status || 201, {
188	                  'Content-Type': 'application/json; charset=utf-8',
189	                  'Content-Length': String(Buffer.byteLength(spec.body || '', 'utf8') + 40),
190	                });
191	                if (spec.body) clientRes.write(spec.body);
192	                setTimeout(() => {
193	                  if (!clientRes.destroyed && clientRes.socket) clientRes.socket.destroy();
194	                }, 50);
195	                return;
196	              }
197	              clientRes.writeHead(spec.status || 201, {
198	                'Content-Type': 'application/json; charset=utf-8',
199	              });
200	              clientRes.end(spec.body ?? realBody);
201	              return;
202	            }
203	          }
204	
205	          if (isRoomsApi && req.method === 'GET' && options.corruptGet) {
206	            const spec = options.corruptGet({ status: proxyRes.statusCode });
207	            if (spec) {
208	              clientRes.writeHead(spec.status, { 'Content-Type': 'application/json; charset=utf-8' });
209	              clientRes.end(spec.body ?? '');
210	              return;
211	            }
212	          }
213	
214	          clientRes.writeHead(proxyRes.statusCode, proxyRes.headers);
215	          clientRes.end(realBody);
216	        });
217	      });
218	      proxyReq.on('error', () => { if (!clientRes.writableEnded) clientRes.destroy(); });
219	      proxyReq.end(Buffer.concat(reqChunks));
220	    };
221	    if (req.complete) forward();
222	    else req.on('end', forward);
223	  });
224	  server.on('connection', (sock) => {
225	    sockets.add(sock);
226	    sock.on('close', () => sockets.delete(sock));
227	  });
228	
229	  return new Promise((resolve) => {
230	    server.listen(0, '127.0.0.1', () => {
231	      const port = server.address().port;
232	      resolve({
233	        url: `http://127.0.0.1:${port}`,
234	        counts,
235	        posts,
236	        async waitForPost(count) {
237	          const deadline = Date.now() + 10000;
238	          while (posts.length < count) {
239	            if (Date.now() > deadline) {
240	              throw new Error(`等待第 ${count} 次创建响应超时（实际 ${posts.length} 次）`);
241	            }
242	            await sleep(10);
243	          }
244	        },
245	        close: async () => {
246	          for (const sock of sockets) sock.destroy();
247	          await new Promise((resolveClose) => server.close(resolveClose));
248	        },
249	      });
250	    });
251	  });
252	}
253	
254	// 每个用例独立的数据目录、真实服务、转发代理与页面；打开页面时已有两条种子
255	// 房间经代理正常加载。
256	async function setupPage(t, proxyOptions = {}) {
257	  const dataDir = await mkdtemp(path.join(tmpdir(), 'score-arena-uidata-'));
258	  t.after(() => rm(dataDir, { recursive: true, force: true }));
259	  await seedRooms(dataDir, SEED_ALPHA, SEED_BETA);
260	  const realURL = await startServer(t, dataDir);
261	  const realPort = Number(new URL(realURL).port);
262	  const proxy = await startProxy(t, realPort, proxyOptions);
263	  t.after(() => proxy.close());
264	
265	  const page = await browser.newPage();
266	  t.after(() => page.close());
267	  await page.goto(proxy.url, { waitUntil: 'load' });
268	  await waitForRowCount(page, 2);
269	  return { page, proxy, realURL };
270	}
271	
272	function waitForRowCount(page, n) {
273	  return page.waitForFunction(
274	    (want) => document.querySelectorAll('#list-area table tbody tr').length === want,
275	    { timeout: 10000 },
276	    n,
277	  );
278	}
279	
280	function waitForMessageKind(page, kind) {
281	  return page.waitForFunction(
282	    (cls) => document.getElementById('form-msg').classList.contains(cls),
283	    { timeout: 10000 },
284	    kind,
285	  );
286	}
287	
288	function readRows(page) {
289	  return page.$$eval('#list-area table tbody tr', (trs) =>
290	    trs.map((tr) => {
291	      const tds = [...tr.querySelectorAll('td')];
292	      return {
293	        cells: tds.map((td) => td.textContent),
294	        timeTitle: tds[6] ? tds[6].getAttribute('title') : null,
295	        badge: tds[5] && tds[5].querySelector('.badge')
296	          ? tds[5].querySelector('.badge').textContent
297	          : null,
298	      };
299	    }),
300	  );
301	}
302	
303	function readFormState(page) {
304	  return page.evaluate(() => ({
305	    name: document.getElementById('name').value,
306	    game: document.getElementById('game').value,
307	    capacity: document.getElementById('capacity').value,
308	    capacityDisabled: document.getElementById('capacity').disabled,
309	    turnSeconds: document.getElementById('turnSeconds').value,
310	    submitDisabled: document.getElementById('submit').disabled,
311	  }));
312	}
313	
314	function readEditable(page) {
315	  return page.evaluate(() => ({
316	    nameDisabled: document.getElementById('name').disabled,
317	    gameDisabled: document.getElementById('game').disabled,
318	    capacityDisabled: document.getElementById('capacity').disabled,
319	    turnDisabled: document.getElementById('turnSeconds').disabled,
320	  }));
321	}
322	
323	function readMessage(page) {
324	  return page.evaluate(() => {
325	    const el = document.getElementById('form-msg');
326	    return { className: el.className, text: el.textContent };
327	  });
328	}
329	
330	async function readServerRooms(baseURL) {
331	  const res = await fetch(baseURL + '/api/rooms');
332	  assert.equal(res.status, 200);
333	  return (await res.json()).rooms;
334	}
335	
336	function assertSeedRows(rows) {
337	  assert.deepEqual(
338	    rows.map((r) => r.cells.slice(0, 6)),
339	    [
340	      ['seed-alpha', '晨间飞行棋', '飞行棋', '4 人', '30 秒', 'playing'],
341	      ['seed-beta', '午夜五子棋', '五子棋', '2 人', '不限时', '未开始'],
342	    ],
343	    '种子房间的展示内容或次序不符合预期',
344	  );
345	}
346	
347	// 合法的飞行棋配置：4 人、60 秒，名称含首尾空格、内部空格与表情。
348	const RAW_NAME = '  周末 飞行棋 🎲 友谊赛  ';
349	const TRIMMED_NAME = '周末 飞行棋 🎲 友谊赛';
350	
351	async function fillLudoForm(page) {
352	  await page.type('#name', RAW_NAME);
353	  await page.select('#game', 'ludo');
354	  await page.waitForFunction(
355	    () => !document.getElementById('capacity').disabled,
356	    { timeout: 5000 },
357	  );
358	  await page.select('#capacity', '4');
359	  await page.type('#turnSeconds', '60');
360	}
361	
362	// 统一断言不确定提醒：固定文案、warn 样式，不含任何成功/编号/失败/连接失败
363	// 信息；forbidden 额外传入本用例正文里出现过、但绝不能被页面拿来展示的
364	// “诱惑值”（真实编号、提交名称等）。
365	async function assertUnconfirmedMessage(page, realId, forbidden) {
366	  const msg = await readMessage(page);
367	  assert.equal(msg.text, UNCONFIRMED_TEXT, '应显示固定的“创建结果未能确认”提醒');
368	  assert.ok(msg.className.includes('warn'), '不确定提醒应以 warn 样式显示');
369	  assert.ok(!msg.className.includes('ok'), '不确定结果不应显示成功样式');
370	  assert.ok(!msg.className.includes('error'), '不确定结果不应显示成输入错误或连接失败');
371	  assert.ok(!msg.text.includes('房间已创建'), '提醒中不应出现“房间已创建”');
372	  assert.ok(!msg.text.includes('编号'), '提醒中不应出现任何编号字样');
373	  assert.ok(!msg.text.includes(realId), '不能显示未确认成功的真实编号');
374	  assert.ok(!msg.text.includes(CONN_FAILURE_TEXT), '不能换成“无法连接服务”');
375	  for (const value of forbidden || []) {
376	    assert.ok(!msg.text.includes(value), `提醒不应从响应内容拼出编号或名称：${value}`);
377	  }
378	  return msg;
379	}
380	
381	// 不确定结果后的统一页面状态断言：四项当前填写原样保留、按钮恢复可用、列表
382	// 维持提交前内容与次序、不自动刷新列表、不自动再次提交。
383	async function assertUnchangedAfterUnconfirmed(page, proxy, initialRows, expectedForm) {
384	  assert.deepEqual(await readFormState(page), expectedForm, '不确定结果后应整体保留当前四项并恢复按钮可用');
385	
386	  // 页面仍允许继续编辑（真实改一下名称验证，而非只看 disabled 属性）。
387	  const editable = await readEditable(page);
388	  assert.deepEqual(editable, {
389	    nameDisabled: false,
390	    gameDisabled: false,
391	    capacityDisabled: false,
392	    turnDisabled: false,
393	  }, '处理结束后四项仍应允许编辑');
394	  await page.type('#name', 'X');
395	  const afterTyping = await readFormState(page);
396	  assert.equal(afterTyping.name, expectedForm.name + 'X', '页面应仍允许继续编辑名称');
397	  assert.equal(afterTyping.submitDisabled, false, '继续编辑时按钮应保持可用');
398	  await page.$eval('#name', (el) => { el.value = el.value.slice(0, -1); });
399	
400	  // 列表维持提交前已展示的房间及次序，不凭提交内容拼出新行。
401	  assert.deepEqual(await readRows(page), initialRows, '不确定结果不应改动房间列表');
402	
403	  // 不自动刷新列表、不自动再次发送创建请求（页面加载后只查询过一次列表）。
404	  await sleep(300);
405	  assert.equal(proxy.counts.getRooms, 1, '不确定结果后不应自动刷新房间列表');
406	  assert.equal(proxy.counts.postRooms, 1, '不确定结果后不应自动再次发送创建请求');
407	  assert.equal(proxy.posts.length, 1, '不应产生第二次创建请求');
408	}
409	
410	// 表格用例的各种 201 异常正文。每一种都必须落到同一种不确定处理。
411	const CORRUPT_VARIANTS = [
412	  {
413	    label: '正文传完前连接断开（Content-Length 大于实际正文）',
414	    spec: { truncate: true, body: '{"id":"' },
415	    forbidden: [],
416	  },
417	  {
418	    label: '正文为空',
419	    spec: { body: '' },
420	    forbidden: [],
421	  },
422	  {
423	    label: '正文不是合法 JSON',
424	    spec: { body: '服务已返回成功但正文损坏{,,' },
425	    forbidden: ['服务已返回成功但正文损坏'],
426	  },
427	  {
428	    label: '正文可解析但缺少编号字段',
429	    // 给出名称等完整配置也不能据此“猜出”编号或拼出房间行。
430	    spec: {
431	      body: JSON.stringify({
432	        name: TRIMMED_NAME, game: 'ludo', capacity: 4, turnSeconds: 60,
433	        status: 'waiting', visibility: 'public',
434	      }),
435	    },
436	    forbidden: [TRIMMED_NAME],
437	  },
438	  {
439	    label: '编号为空字符串',
440	    spec: { body: JSON.stringify({ id: '', name: TRIMMED_NAME }) },
441	    forbidden: [TRIMMED_NAME],
442	  },
443	  {
444	    label: '编号为数字（类型不符）',
445	    spec: { body: JSON.stringify({ id: 12345, name: TRIMMED_NAME }) },
446	    forbidden: ['12345', TRIMMED_NAME],
447	  },
448	  {
449	    label: '编号为 null（类型不符）',
450	    spec: { body: JSON.stringify({ id: null, name: TRIMMED_NAME }) },
451	    forbidden: [TRIMMED_NAME],
452	  },
453	  {
454	    label: '编号为数组（类型不符），内含诱惑编号',
455	    spec: { body: JSON.stringify({ id: ['guessed-room-id'], name: TRIMMED_NAME }) },
456	    forbidden: ['guessed-room-id', TRIMMED_NAME],
457	  },
458	];
459	
460	for (const variant of CORRUPT_VARIANTS) {
461	  test(`201 但创建结果未能确认（${variant.label}）：显示不确定提醒、保留填写、列表不变；房间实际已保存，刷新后可见`, { timeout: 60000 }, async (t) => {
462	    // 第一次创建请求在真实保存后被替换成异常正文；之后（刷新页面、再次提交）
463	    // 一律透传真实响应。
464	    let corruptOnce = true;
465	    const { page, proxy, realURL } = await setupPage(t, {
466	      corruptPost: () => {
467	        if (!corruptOnce) return null;
468	        corruptOnce = false;
469	        return variant.spec;
470	      },
471	    });
472	
473	    const initialRows = await readRows(page);
474	    assertSeedRows(initialRows);
475	    const beforeRooms = await readServerRooms(realURL);
476	    assert.equal(beforeRooms.length, 2);
477	
478	    await fillLudoForm(page);
479	    await page.click('#submit');
480	
481	    // 等待不确定提醒出现（不是成功提示，也不是输入错误/连接失败）。
482	    await waitForMessageKind(page, 'warn');
483	    await proxy.waitForPost(1);
484	    const post = proxy.posts[0];
485	
486	    // 真实服务确实按提交时配置保存成功：代理拿到的是完整 201 与非空真实编号，
487	    // 只是发给浏览器的正文被本用例替换/截断。
488	    assert.equal(post.status, 201, '代理转发的真实响应应为 201');
489	    assert.ok(post.room && typeof post.room.id === 'string' && post.room.id !== '',
490	      '真实服务应已保存并生成非空字符串编号');
491	    assert.deepEqual(JSON.parse(post.reqBody), {
492	      name: RAW_NAME,
493	      game: 'ludo',
494	      capacity: 4,
495	      turnSeconds: 60,
496	    }, '请求体应是提交时的合法配置（名称保留输入原貌）');
497	    const realId = post.room.id;
498	    assert.equal(post.room.name, TRIMMED_NAME, '服务端保存名称应仅去首尾空白');
499	    assert.equal(post.room.game, 'ludo');
500	    assert.equal(post.room.capacity, 4);
501	    assert.equal(post.room.turnSeconds, 60);
502	
503	    // 页面侧：固定的不确定提醒，不显示编号/名称，不换成其他含义的提示。
504	    await assertUnconfirmedMessage(page, realId, variant.forbidden);
505	
506	    // 名称首尾空白保持输入原貌，四项整体保留；不沿用正常成功的清空行为。
507	    await assertUnchangedAfterUnconfirmed(page, proxy, initialRows, {
508	      name: RAW_NAME,
509	      game: 'ludo',
510	      capacity: '4',
511	      capacityDisabled: false,
512	      turnSeconds: '60',
513	      submitDisabled: false,
514	    });
515	
516	    // 服务端记录确实增加了这一间（页面没有成功提示不代表服务端没有新增）。
517	    const savedRooms = await readServerRooms(realURL);
518	    assert.equal(savedRooms.length, 3, '服务端应已保存本次房间');
519	    assert.deepEqual(savedRooms.slice(0, 2), beforeRooms, '已有记录及附带字段保持原值');
520	    const saved = savedRooms[2];
521	    assert.equal(saved.id, realId, '服务端真实编号以代理读到的创建结果为准');
522	    assert.equal(saved.name, TRIMMED_NAME);
523	    assert.equal(saved.game, 'ludo');
524	    assert.equal(saved.capacity, 4);
525	    assert.equal(saved.turnSeconds, 60);
526	
527	    // 用户按提醒刷新页面：应看到这次已保存的房间及真实编号，追加在种子之后；
528	    // 刷新不会再次提交（没有因等待/保留状态自动多建一间房）。
529	    await page.reload({ waitUntil: 'load' });
530	    await waitForRowCount(page, 3);
531	    const rowsAfterReload = await readRows(page);
532	    assert.deepEqual(
533	      rowsAfterReload.slice(0, 2).map((r) => r.cells),
534	      initialRows.map((r) => r.cells),
535	      '刷新后原有房间的内容与次序应保持',
536	    );
537	    const newRow = rowsAfterReload[2];
538	    assert.equal(newRow.cells[0], realId, '刷新后应显示已保存房间的真实编号');
539	    assert.equal(newRow.cells[1], TRIMMED_NAME);
540	    assert.equal(newRow.cells[2], '飞行棋');
541	    assert.equal(newRow.cells[3], '4 人');
542	    assert.equal(newRow.cells[4], '60 秒');
543	    assert.equal(newRow.cells[5], '未开始');
544	    assert.equal(newRow.badge, '未开始');
545	    assert.equal(newRow.timeTitle, saved.createdAt);
546	
547	    const finalRooms = await readServerRooms(realURL);
548	    assert.equal(finalRooms.length, 3, '刷新前后的等待/保留状态不应自动生成另一间房');
549	    assert.equal(finalRooms[2].id, realId);
550	    assert.equal(proxy.counts.postRooms, 1, '整个过程中应只发送过一次创建请求');
551	  });
552	}
553	
554	// 等待期间改成另一份配置时收到不确定结果：保留“结果到达时”的最新填写，
555	// 人数选择状态与当前规则一致；服务端保存的是提交时快照；刷新后只看到
556	// 提交时那一间，等待期间的编辑没有自动生成另一间房。
557	test('等待期间改成另一份配置后收到 201 截断响应：保留到达时最新四项，已保存的是提交时快照，刷新无额外房间', { timeout: 60000 }, async (t) => {
558	  let releaseGate;
559	  const { page, proxy, realURL } = await setupPage(t, {
560	    // 真实响应到达后先挂住，让测试在“等待期间”完成编辑，再放行残缺正文。
561	    corruptPost: () => new Promise((resolve) => {
562	      releaseGate = () => resolve({ truncate: true, body: '{"id":"' });
563	    }),
564	  });
565	
566	  const initialRows = await readRows(page);
567	  assertSeedRows(initialRows);
568	  const beforeRooms = await readServerRooms(realURL);
569	
570	  // 提交时：五子棋/2 人/30 秒，名称带首尾空白。
571	  const submittedName = '  提交时的五子棋房间  ';
572	  await page.type('#name', submittedName);
573	  await page.select('#game', 'gomoku');
574	  await page.waitForFunction(
575	    () => !document.getElementById('capacity').disabled &&
576	      document.getElementById('capacity').value === '2',
577	    { timeout: 5000 },
578	  );
579	  await page.type('#turnSeconds', '30');
580	  await page.click('#submit');
581	
582	  // 真实服务已保存但响应被代理挂住：等待期间按钮不可用。
583	  await proxy.waitForPost(1);
584	  assert.equal((await readFormState(page)).submitDisabled, true, '等待期间按钮应不可用');
585	  assert.deepEqual(JSON.parse(proxy.posts[0].reqBody), {
586	    name: submittedName,
587	    game: 'gomoku',
588	    capacity: 2,
589	    turnSeconds: 30,
590	  }, '请求体必须固定为点击提交时的配置快照');
591	
592	  // 等待期间改成另一份完整合法的飞行棋配置。
593	  await page.$eval('#name', (el) => { el.value = ''; });
594	  await page.type('#name', '等待中改成飞行棋');
595	  await page.select('#game', 'ludo');
596	  await page.waitForFunction(
597	    () => !document.getElementById('capacity').disabled,
598	    { timeout: 5000 },
599	  );
600	  await page.select('#capacity', '4');
601	  await page.$eval('#turnSeconds', (el) => { el.value = ''; });
602	  await page.type('#turnSeconds', '90');
603	
604	  const editable = await readEditable(page);
605	  assert.deepEqual(editable, {
606	    nameDisabled: false,
607	    gameDisabled: false,
608	    capacityDisabled: false,
609	    turnDisabled: false,
610	  }, '等待期间四项应仍可编辑');
611	
612	  // 重复点击或绕过禁用直接派发 submit，都不能发出第二次创建请求。
613	  await page.click('#submit');
614	  await page.evaluate(() => {
615	    document.getElementById('room-form')
616	      .dispatchEvent(new Event('submit', { bubbles: true, cancelable: true }));
617	  });
618	  await sleep(300);
619	  assert.equal(proxy.posts.length, 1, '等待期间不得发出第二次创建请求');
620	
621	  // 放行：浏览器收到 201 但正文被截断。
622	  releaseGate();
623	  await waitForMessageKind(page, 'warn');
624	  const realId = proxy.posts[0].room.id;
625	  await assertUnconfirmedMessage(page, realId, ['等待中改成飞行棋', '提交时的五子棋房间']);
626	
627	  // 保留结果到达时的最新填写（飞行棋/4 人/90 秒），人数选择与当前规则一致；
628	  // 不回退到提交时的五子棋，也不按正常成功清空。
629	  await assertUnchangedAfterUnconfirmed(page, proxy, initialRows, {
630	    name: '等待中改成飞行棋',
631	    game: 'ludo',
632	    capacity: '4',
633	    capacityDisabled: false,
634	    turnSeconds: '90',
635	    submitDisabled: false,
636	  });
637	
638	  // 服务端保存的是提交时的五子棋快照，且只有这一间新房间。
639	  const savedRooms = await readServerRooms(realURL);
640	  assert.equal(savedRooms.length, 3, '等待期间的编辑不得自动创建另一个房间');
641	  assert.deepEqual(savedRooms.slice(0, 2), beforeRooms);
642	  const saved = savedRooms[2];
643	  assert.equal(saved.id, realId);
644	  assert.equal(saved.name, '提交时的五子棋房间', '服务端应只去掉名称首尾空白');
645	  assert.equal(saved.game, 'gomoku');
646	  assert.equal(saved.capacity, 2);
647	  assert.equal(saved.turnSeconds, 30);
648	
649	  // 刷新页面：看到提交时保存的五子棋房间及真实编号，不会多出飞行棋房间。
650	  await page.reload({ waitUntil: 'load' });
651	  await waitForRowCount(page, 3);
652	  const rows = await readRows(page);
653	  assert.equal(rows[2].cells[0], realId, '刷新后应显示已保存房间的真实编号');
654	  assert.equal(rows[2].cells[1], '提交时的五子棋房间');
655	  assert.equal(rows[2].cells[2], '五子棋');
656	  assert.equal(rows[2].cells[3], '2 人');
657	  assert.equal(rows[2].cells[4], '30 秒');
658	  const finalRooms = await readServerRooms(realURL);
659	  assert.equal(finalRooms.length, 3, '刷新后仍应只有提交时创建的一间房');
660	  assert.equal(finalRooms[2].id, realId);
661	});
662	
663	// 对照：完整的创建结果（201 + 非空字符串编号）仍按正常成功处理——显示返回
664	// 编号、复位表单并刷新列表，不显示不确定提醒。
665	test('对照：完整创建结果仍按正常成功处理，显示编号、复位表单并更新列表', { timeout: 60000 }, async (t) => {
666	  // 不传任何代理选项：所有请求透传真实服务。
667	  const { page, proxy, realURL } = await setupPage(t);
668	  const initialRows = await readRows(page);
669	  assertSeedRows(initialRows);
670	
671	  await fillLudoForm(page);
672	  await page.click('#submit');
673	
674	  await waitForMessageKind(page, 'ok');
675	  await proxy.waitForPost(1);
676	  const created = proxy.posts[0].room;
677	  assert.equal(proxy.posts[0].status, 201);
678	  assert.ok(created.id && typeof created.id === 'string');
679	
680	  const msg = await readMessage(page);
681	  assert.equal(msg.text, SUCCESS_PREFIX + created.id, '完整结果应显示普通成功提示与编号');
682	  assert.ok(!msg.text.includes('创建结果未能确认'), '完整结果不应显示不确定提醒');
683	
684	  await waitForRowCount(page, 3);
685	  assert.deepEqual(await readFormState(page), RESET_FORM, '正常成功后表单应复位');
686	
687	  const rows = await readRows(page);
688	  assert.deepEqual(rows.slice(0, 2), initialRows);
689	  assert.equal(rows[2].cells[0], created.id);
690	  assert.equal(rows[2].cells[1], TRIMMED_NAME);
691	  assert.equal(rows[2].cells[2], '飞行棋');
692	  assert.equal(rows[2].cells[3], '4 人');
693	  assert.equal(rows[2].cells[4], '60 秒');
694	
695	  const serverRooms = await readServerRooms(realURL);
696	  assert.equal(serverRooms.length, 3);
697	  assert.equal(serverRooms[2].id, created.id);
698	});
699	
700	// 对照：已确认创建成功（拿到非空编号）但随后的列表刷新失败时，仍保留成功
701	// 提示及编号，不按不确定结果或创建连接失败处理。
702	test('对照：已确认成功但列表刷新失败时保留成功提示与编号，不显示不确定提醒', { timeout: 60000 }, async (t) => {
703	  // 打开页面的第一次列表查询透传；创建成功后的列表查询返回 500。
704	  let listSeen = 0;
705	  const { page, proxy, realURL } = await setupPage(t, {
706	    corruptGet: () => {
707	      listSeen++;
708	      if (listSeen === 1) return null; // 首次加载正常
709	      return { status: 500, body: JSON.stringify({ error: '模拟列表读取失败' }) };
710	    },
711	  });
712	  const initialRows = await readRows(page);
713	  assertSeedRows(initialRows);
714	
715	  await fillLudoForm(page);
716	  await page.click('#submit');
717	
718	  await waitForMessageKind(page, 'ok');
719	  await proxy.waitForPost(1);
720	  const created = proxy.posts[0].room;
721	  assert.ok(created.id, '创建结果应包含非空编号');
722	
723	  const msg = await readMessage(page);
724	  assert.ok(msg.text.startsWith(SUCCESS_PREFIX), `应保留成功提示，实际: ${msg.text}`);
725	  assert.equal(msg.text.slice(SUCCESS_PREFIX.length), created.id, '提示编号应与创建结果一致');
726	  assert.ok(!msg.text.includes('创建结果未能确认'), '已确认成功不应显示不确定提醒');
727	  assert.ok(!msg.text.includes(CONN_FAILURE_TEXT), '已确认成功不应显示连接失败提示');
728	
729	  // 表单仍按正常成功复位，按钮恢复可用。
730	  assert.deepEqual(await readFormState(page), RESET_FORM);
731	
732	  // 列表区域显示加载失败，而不是保留旧表格或显示不确定提醒。
733	  await page.waitForFunction(
734	    () => document.querySelector('#list-area .list-error')?.textContent ===
735	      '房间列表加载失败，请稍后刷新重试。已有数据不会因此丢失。',
736	    { timeout: 10000 },
737	  );
738	  const listText = await page.$eval('#list-area', (el) => el.textContent);
739	  assert.ok(listText.includes(LIST_ERROR_TEXT));
740	
741	  // 服务端确实已保存本次创建。
742	  const serverRooms = await readServerRooms(realURL);
743	  assert.equal(serverRooms.length, 3);
744	  assert.equal(serverRooms[2].id, created.id);
745	});
