// 名称首尾空白采用 Unicode 空白范围：U+0085、U+00A0 等应去掉，
// U+FEFF 不属于该范围，应保留并计入长度；内部空白原样保留。
func TestCreateRoomTrimsUnicodeWhitespaceButKeepsFEFF(t *testing.T) {
	dataDir := t.TempDir()
